// Test the custom V8 patched replaceIf for array
// We exercise the code path with mutations in callback: length change, store object, sparsify, change __proto__, and defineProperty
function log(title, value) {
    print('--- ' + title + ' ---');
    print('Returned:', value);
}

function dump_arr(arr) {
    print('Array:', arr);
    for (let i = 0; i < arr.length; ++i) {
        print(`  arr[${i}] =`, arr[i]);
    }
