// JavaScript tests for exotic scenarios on Array.prototype.replaceIf
d8.print = print;

let log = d8.print;

function test1() {
  log("\n[1] Normal Array, normal callback");
  let arr = [1, 2, 3];
  let called = false;
  let res = arr.replaceIf(1, (x) => { called = true; return true; }, 999);
  log("called?", called, "result:", res, "arr:", arr);
}

function test2() {
  log("\n[2] Array with custom getter that throws");
  let arr = [1,2,3];
  Object.defineProperty(arr, 1, {
    get() { throw new Error('getter-throw'); }, configurable:true
  });
  try {
    arr.replaceIf(1, (x) => { return true; }, 999);
  } catch(e) {
    log("threw as expected:", e);
  }
}

function test3() {
  log("\n[3] Proxy as 'this', trap get throws");
  let arr = [1,2,3];
  let proxy = new Proxy(arr, {
    get(t, p, r) {
      if (p === '1') throw 'proxy-get-ex';
      return Reflect.get(t, p, r);
    }
  });
  try {
    proxy.replaceIf(1, (x) => true, 666);
  } catch(e) {
    log("proxy.get trapped:", e);
  }
}

function test4() {
  log("\n[4] Proxy, replace callback throws");
  let arr = [41,43,44];
  let proxy = new Proxy(arr, {});
  try {
    proxy.replaceIf(0, () => { throw 'cbfail'; }, 123);
  } catch(e) {
    log("callback threw:", e);
  }
}

function test5() {
  log("\n[5] TypedArray as 'this'");
  let ta = new Uint32Array([10, 20, 30]);
  try {
    ta.replaceIf(1, (x) => true, 1234);
    log('typed array replace ok:', ta[1]);
  } catch(e) {
    log('typed array failure:', e);
  }
}

function test6() {
  log("\n[6] Callback mutates length in place");
  let arr = [5,6,7,8];
  let cb = function(x) {
    arr.length = 1; // shrink length in callback
    return true;
  };
  let res = arr.replaceIf(2, cb, 789);
  log('result:', res, 'arr:', arr);
}

function test7() {
  log("\n[7] Callback replaces 'this' in use");
  let arr = [11,12,13,14];
  let cb = function(x) {
    arr[2] = undefined; arr.length = 2;
    return true;
  };
  arr.replaceIf(2, cb, 2024);
  log('resulting arr:', arr);
}

test1();
test2();
test3();
test4();
test5();
test6();
test7();

