// Exhaustive test for Array.prototype.replaceIf edge cases
function log(title, fn) {
  try {
    print(title + ': ' + fn());
  } catch (e) {
    print(title + ' threw: ' + (e.stack || e));
  }
}

// Test normal object as 'this'
log('Plain object as this', () => {
    let o = {0: 'X', length: 1};
    return Array.prototype.replaceIf.call(o, 0, (e) => true, 42);
});

// Custom getter throws
log('Custom getter throws', () => {
    let o = {get 0() { throw new Error('Uh Oh'); }, length: 1};
    return Array.prototype.replaceIf.call(o, 0, (e) => true, 42);
});

// Callback throws
log('Callback throws', () => {
    let arr = [1];
    return Array.prototype.replaceIf.call(arr, 0, (e) => {throw new Error('CB fail');}, 123);
});

// Proxy with all traps logging
log('Proxy for this', () => {
    let arr = [1,2,3];
    let seen = [];
    let proxy = new Proxy(arr, {
        get(t, p, r) { seen.push(`get:${p}`); return t[p]; },
        set(t, p, v, r) { seen.push(`set:${p}`); t[p] = v; return true; }
    });
    let ret = Array.prototype.replaceIf.call(proxy, 1, (e) => true, 99);
    return ret + ', seen=' + seen.join(',');
});

// Proxy target with evil handler (crashes or odd behavior)
log('Proxy handler throws', () => {
    let arr = [5];
    let proxy = new Proxy(arr, {
        get: function(t,p,r){if(p==='0') throw new Error('trap'); return t[p];}
    });
    return Array.prototype.replaceIf.call(proxy, 0, (e) => true, 7);
});

// Typed array as this
log('Typed array as this', () => {
    let t = new Uint32Array(4);
    t[2] = 5;
    return Array.prototype.replaceIf.call(t, 2, (e) => true, 1337);
});

// Array with length property changing
log('Array length shrinks in callback', () => {
    let arr = [1,2,3];
    return Array.prototype.replaceIf.call(arr, 2, function(e) {
      arr.length = 1;
      return true;
    }, 77);
});

// Callback with side effect on prototype (deletes indexed property)
log('Array indexed delete in callback', () => {
    let arr = [10,11,12];
    return Array.prototype.replaceIf.call(arr, 1, function(e) {
      delete arr[1];
      return true;
    }, 21);
});

// Callback sets replacement on array prototype
log('Callback sets on Array.prototype', () => {
    let arr = [1];
    return Array.prototype.replaceIf.call(arr, 0, function(e) {
      Array.prototype[0] = 'abc';
      return true;
    }, 'DEF');
});

